CREATE TABLE daily_category_totals(date TEXT NOT NULL,category_id TEXT NOT NULL REFERENCES categories(id),currency TEXT NOT NULL,spending_micros INTEGER NOT NULL,income_micros INTEGER NOT NULL,transaction_count INTEGER NOT NULL,PRIMARY KEY(date,category_id,currency));
CREATE TABLE daily_merchant_totals(date TEXT NOT NULL,merchant_id TEXT NOT NULL,currency TEXT NOT NULL,spending_micros INTEGER NOT NULL,transaction_count INTEGER NOT NULL,PRIMARY KEY(date,merchant_id,currency));
CREATE TABLE monthly_financial_metrics(month TEXT NOT NULL,currency TEXT NOT NULL,income_micros INTEGER NOT NULL,spending_micros INTEGER NOT NULL,net_cashflow_micros INTEGER NOT NULL,savings_rate REAL,PRIMARY KEY(month,currency));
CREATE VIEW effective_transactions AS SELECT t.*, f.category_id, f.merchant, f.kind,f.classification_source,f.refund_of,COALESCE(a.exclude_from_spending,0) AS excluded,a.note FROM transactions t JOIN transaction_facts f ON f.transaction_id=t.id LEFT JOIN transaction_annotations a ON a.transaction_id=t.id WHERE t.is_removed=0;
